CREATE DATABASE IF NOT EXISTS dtjob CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dtjob;
SET NAMES utf8mb4;
DROP TABLE IF EXISTS applications; DROP TABLE IF EXISTS ads; DROP TABLE IF EXISTS people; DROP TABLE IF EXISTS categories; DROP TABLE IF EXISTS companies;
CREATE TABLE companies(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,description TEXT,website VARCHAR(255),location VARCHAR(150),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE people(id INT AUTO_INCREMENT PRIMARY KEY,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ads(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,short_description VARCHAR(300) NOT NULL,full_description TEXT NOT NULL,salary_min INT,salary_max INT,location VARCHAR(150),contract_type ENUM('CDI','CDD','internship','apprenticeship','freelance') NOT NULL,working_time ENUM('full_time','part_time') NOT NULL DEFAULT 'full_time',is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,company_id INT NOT NULL,category_id INT NOT NULL,contact_person_id INT NULL,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(contact_person_id) REFERENCES people(id) ON DELETE SET NULL);
CREATE TABLE applications(id INT AUTO_INCREMENT PRIMARY KEY,ad_id INT NOT NULL,person_id INT NOT NULL,message TEXT NOT NULL,applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,status ENUM('pending','accepted','rejected') NOT NULL DEFAULT 'pending',email_sent BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(ad_id) REFERENCES ads(id) ON DELETE CASCADE,FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE CASCADE,UNIQUE(ad_id,person_id));
